# UTF-8 safe updater (base64-embedded). No encoding issues possible.
$ErrorActionPreference = 'Stop'
$root = (Get-Location).Path
Write-Host 'Updating files (base64 decode)...'

function Write-FileB64($relPath, $b64) {
    $target = Join-Path $root $relPath
    $dir = Split-Path $target -Parent
    if (-not (Test-Path $dir)) { New-Item -ItemType Directory -Force -Path $dir | Out-Null }
    $bytes = [System.Convert]::FromBase64String($b64)
    [System.IO.File]::WriteAllBytes($target, $bytes)
    Write-Host ('  yazildi: ' + $relPath)
}

Write-FileB64 'README.md' ''
Write-FileB64 'YuzYuze\A-Grubu\README.md' ''
Write-FileB64 'YuzYuze\A-Grubu\Hafta-02-Veri-Analizi-ve-Gorsellestirme\README.md' ''
Write-FileB64 'YuzYuze\A-Grubu\Hafta-03-Kod-Yazmadan-Ajanlar-ve-Agent-Mimarisi\README.md' ''
Write-FileB64 'YuzYuze\A-Grubu\Hafta-04-Otonom-Arastirma-Ajanlari-ve-Ders-Materyali\README.md' ''
Write-FileB64 'YuzYuze\B-Grubu\Hafta-03-YZ-Ajanlari-ve-Baglam-Yonetimi\README.md' ''

# Eski klasorleri sil
$old = Join-Path $root 'YuzYuze\A-Grubu\Hafta-04-AI-ile-Gorsel-Video-Uretimi-ve-Marka-Kimligi'
if (Test-Path $old) { Remove-Item -Recurse -Force $old; Write-Host ('  silindi: YuzYuze\A-Grubu\Hafta-04-AI-ile-Gorsel-Video-Uretimi-ve-Marka-Kimligi') }
$old = Join-Path $root 'YuzYuze\A-Grubu\Hafta-05-Otonom-Arastirma-Ajanlari-ve-Ders-Materyali'
if (Test-Path $old) { Remove-Item -Recurse -Force $old; Write-Host ('  silindi: YuzYuze\A-Grubu\Hafta-05-Otonom-Arastirma-Ajanlari-ve-Ders-Materyali') }

Write-Host 'Done.'